using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;
public sealed class AppearanceTheme {
 public string id="",name="Mon thème",mode="solid",color1="#181817",color2="#453523",color3="#69502D",card="#222221",accent="#F6AD42";
 public bool third=false;public double angle=0,intensity=100,opacity=96;
}
internal sealed class ThemePalette {
 internal Color Ink,Muted,Card,Surface,Border,Chrome,Accent,AccentText,Base;internal Brush Background,CardBrush;
}
internal static class Appearance {
 internal static AppearanceTheme Clone(AppearanceTheme t){return new AppearanceTheme{id=t.id,name=t.name,mode=t.mode,color1=t.color1,color2=t.color2,color3=t.color3,card=t.card,accent=t.accent,third=t.third,angle=t.angle,intensity=t.intensity,opacity=t.opacity};}
 internal static string Hex(Color c){return String.Format("#{0:X2}{1:X2}{2:X2}",c.R,c.G,c.B);}
 internal static Color Parse(string value){if(value==null||value.Length!=7||value[0]!='#'||value.Skip(1).Any(c=>!Uri.IsHexDigit(c)))throw new InvalidDataException("Couleur invalide : utilisez #RRGGBB.");return (Color)ColorConverter.ConvertFromString(value);}
 internal static Color Mix(Color a,Color b,double amount){return Color.FromRgb((byte)Math.Round(a.R+(b.R-a.R)*amount),(byte)Math.Round(a.G+(b.G-a.G)*amount),(byte)Math.Round(a.B+(b.B-a.B)*amount));}
 static double Linear(byte channel){double c=channel/255.0;return c<=.04045?c/12.92:Math.Pow((c+.055)/1.055,2.4);}
 internal static double Luminance(Color c){return .2126*Linear(c.R)+.7152*Linear(c.G)+.0722*Linear(c.B);}
 internal static double Contrast(Color a,Color b){double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
 internal static Color TextOn(Color background){var light=Parse("#F3EBDD");var dark=Parse("#211E19");var chosen=Contrast(light,background)>=Contrast(dark,background)?light:dark;if(Contrast(chosen,background)<4.5)chosen=Contrast(Colors.White,background)>=Contrast(Colors.Black,background)?Colors.White:Colors.Black;return chosen;}
 static Color Readable(Color color,Color background,Color towards,double minimum){for(int i=0;i<30&&Contrast(color,background)<minimum;i++)color=Mix(color,towards,.12);return color;}
 internal static ThemePalette Palette(AppearanceTheme t){var card=Parse(t.card);var ink=TextOn(card);bool light=Luminance(ink)<.25;var baseColor=Parse(light?"#F1EEE8":"#181817");var surface=Mix(card,light?Colors.White:Colors.Black,.12);var accent=Parse(t.accent);var muted=Readable(Mix(ink,card,.34),card,ink,4.5);var first=Readable(Mix(baseColor,Parse(t.color1),t.intensity/100),ink,baseColor,4.5);var second=Readable(Mix(baseColor,Parse(t.color2),t.intensity/100),ink,baseColor,4.5);var third=Readable(Mix(baseColor,Parse(t.color3),t.intensity/100),ink,baseColor,4.5);first=Readable(first,muted,baseColor,4.5);second=Readable(second,muted,baseColor,4.5);third=Readable(third,muted,baseColor,4.5);Brush background;if(t.mode=="solid")background=new SolidColorBrush(first);else{double angle=t.angle*Math.PI/180;var brush=new LinearGradientBrush{StartPoint=new Point(.5-.5*Math.Cos(angle),.5-.5*Math.Sin(angle)),EndPoint=new Point(.5+.5*Math.Cos(angle),.5+.5*Math.Sin(angle))};brush.GradientStops.Add(new GradientStop(first,0));if(t.mode=="two"){brush.GradientStops.Add(new GradientStop(first,.5));brush.GradientStops.Add(new GradientStop(second,.5));}else if(t.third)brush.GradientStops.Add(new GradientStop(second,.5));brush.GradientStops.Add(new GradientStop(t.mode=="gradient"&&t.third?third:second,1));background=brush;}var cardColor=Color.FromArgb((byte)Math.Round(t.opacity/100*255),card.R,card.G,card.B);return new ThemePalette{Ink=ink,Muted=muted,Card=card,Surface=surface,Border=Mix(card,ink,.16),Chrome=Mix(card,baseColor,.35),Accent=accent,AccentText=Readable(accent,card,ink,4.5),Base=baseColor,Background=background,CardBrush=new SolidColorBrush(cardColor)};}
 internal static void ValidateTheme(AppearanceTheme t){if(t==null||String.IsNullOrWhiteSpace(t.name)||t.name.Length>40||!new[]{"solid","two","gradient"}.Contains(t.mode)||Double.IsNaN(t.angle)||Double.IsInfinity(t.angle)||t.angle<0||t.angle>360||Double.IsNaN(t.intensity)||t.intensity<0||t.intensity>100||Double.IsNaN(t.opacity)||t.opacity<85||t.opacity>100)throw new InvalidDataException("Thème invalide.");foreach(string color in new[]{t.color1,t.color2,t.color3,t.card,t.accent})Parse(color);}
 internal static void Validate(Settings settings){if(settings.Appearance==null){settings.Appearance=new AppearanceTheme();try{settings.Appearance.accent=Hex((Color)ColorConverter.ConvertFromString(settings.Accent));}catch{}}ValidateTheme(settings.Appearance);settings.Accent=settings.Appearance.accent;if(settings.SavedThemes==null)settings.SavedThemes=new List<AppearanceTheme>();if(settings.SavedThemes.Count>30)throw new InvalidDataException("Limite : 30 thèmes enregistrés.");var ids=new HashSet<string>();foreach(var theme in settings.SavedThemes){ValidateTheme(theme);if(String.IsNullOrEmpty(theme.id)||!ids.Add(theme.id)){theme.id=Guid.NewGuid().ToString();ids.Add(theme.id);}}}
 internal static List<AppearanceTheme> Presets(){return new List<AppearanceTheme>{new AppearanceTheme{name="Original"},new AppearanceTheme{name="Ardoise & cuivre",mode="gradient",color1="#182321",color2="#51402C",card="#222B28",accent="#E4AA70",intensity=80,angle=45},new AppearanceTheme{name="Bleu nuit",mode="gradient",color1="#152738",color2="#263B43",card="#202A31",accent="#8FC8D4",angle=90},new AppearanceTheme{name="Sable",mode="two",color1="#ECE4D5",color2="#D8C5A7",card="#F6F0E6",accent="#805326",angle=45,opacity=96}};}
 internal static void Test(string folder){var s=new Settings{Accent="#83CBB7"};Validate(s);if(s.Appearance.accent!="#83CBB7")throw new Exception("Migration couleur");foreach(var t in Presets()){ValidateTheme(t);var palette=Palette(t);if(Contrast(palette.Ink,palette.Card)<4.5||Contrast(palette.Muted,palette.Card)<4.5)throw new Exception("Contraste du thème");}foreach(string color in new[]{"#000000","#FFFFFF","#777777","#808080","#D56533","#266A8F"}){var palette=Palette(new AppearanceTheme{card=color,mode="gradient",color1="#FFFFFF",color2="#000000",opacity=85});if(Contrast(palette.Ink,palette.Card)<4.5)throw new Exception("Contraste d’une couleur personnalisée");}var g=new AppearanceTheme{mode="gradient",third=true,angle=90};if(((LinearGradientBrush)Palette(g).Background).GradientStops.Count!=3)throw new Exception("Dégradé à 3 couleurs");g.mode="two";if(((LinearGradientBrush)Palette(g).Background).GradientStops.Count!=4)throw new Exception("Fond bicolore");var store=new Store(Path.Combine(folder,"appearance"));store.Value.settings.Appearance=g;store.Value.settings.SavedThemes.Add(Clone(g));store.Save();store=new Store(store.Root);if(store.Value.settings.Appearance.mode!="two"||store.Value.settings.SavedThemes.Count!=1)throw new Exception("Persistance des thèmes");bool bad=false;try{ValidateTheme(new AppearanceTheme{color1="url(http://example.com)"});}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Couleur invalide acceptée");}
}
